import{_ as t,c as s,o as r,a3 as n}from"./chunks/framework.CoV49S2T.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/faq.md","filePath":"fr/guide/faq.md","lastUpdated":1786612388000}'),a={name:"fr/guide/faq.md"};function o(i,e,p,l,u,c){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p><strong>Q : Qu&#39;est-ce que ClipboardxAI ?</strong></p><p>R : ClipboardxAI est un gestionnaire de presse-papiers intelligent pour macOS. Il conserve un historique consultable de tout ce que vous copiez et vous permet d&#39;exécuter des actions dessus — résumer, traduire, mettre en forme le texte, ou l&#39;envoyer à un modèle d&#39;IA cloud.</p><p><strong>Q : Quelles versions de macOS sont prises en charge ?</strong></p><p>R : macOS 14 Sonoma ou version ultérieure, optimisé pour Apple Silicon (série M) avec prise en charge Intel.</p><p><strong>Q : Comment l&#39;installer ?</strong></p><p>R : Téléchargez depuis le <a href="/fr/">Mac App Store</a> (recommandé) ou récupérez la dernière version depuis <s><a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub Releases</a></s>. Voir le <a href="/fr/guide/installation.html">Guide d&#39;installation</a>.</p><p><strong>Q : ClipboardxAI est-il gratuit ?</strong></p><p>R : ClipboardxAI est une application payante sur le Mac App Store. Après l&#39;achat, tous les outils locaux intégrés sont inclus et aucun compte n&#39;est requis. Les actions IA cloud utilisent la clé API <em>de votre propre</em> fournisseur, vous ne payez donc directement que le fournisseur d&#39;IA — il n&#39;y a aucun niveau payant supplémentaire dans l&#39;application.</p><p><strong>Q : Quels fournisseurs d&#39;IA sont pris en charge ?</strong></p><p>R : Tout fournisseur compatible OpenAI : DeepSeek, MiniMax, Zhipu GLM, Kimi (Moonshot), Mistral, et l&#39;Ollama local — ainsi qu&#39;OpenAI, Anthropic et Gemini. Votre clé est stockée dans le Keychain.</p><p><strong>Q : Fonctionne-t-il hors ligne ?</strong></p><p>R : Oui. L&#39;historique du presse-papiers et les outils locaux intégrés (extraire les liens, compter les statistiques, réduire les lignes vides, et plus encore) s&#39;exécutent entièrement sur votre Mac sans connexion Internet.</p><p><strong>Q : Mes données de presse-papiers sont-elles privées ?</strong></p><p>R : Votre historique reste sur votre appareil. L&#39;IA cloud est optionnelle et n&#39;envoie le contenu qu&#39;au fournisseur que vous configurez, à l&#39;aide d&#39;une clé de votre Keychain. Nous ne recevons ni ne stockons vos éléments, et il n&#39;y a aucune télémétrie. Voir la <a href="/fr/guide/privacy.html">Politique de confidentialité</a>.</p><p><strong>Q : Comment ajouter davantage d&#39;actions ?</strong></p><p>R : Parcourez le <a href="/fr/marketplace/">Marketplace</a> et cliquez sur <strong>Installer</strong> sur une action. Celle-ci ouvre l&#39;application via un lien profond et apparaît dans votre liste <strong>Installés</strong>.</p><p><strong>Q : Comment mettre à jour l&#39;application ?</strong></p><p>R : La version du Mac App Store se met à jour automatiquement. <s>Pour les versions GitHub, téléchargez la dernière version et remplacez l&#39;application dans <code>Applications</code>.</s></p><p><strong>Q : Comment signaler des bugs ou demander des fonctionnalités ?</strong></p><p>R : Ouvrez un ticket sur le <a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">dépôt GitHub</a>. Incluez votre version de macOS, la version de l&#39;application et les étapes pour reproduire.</p><p><strong>Q : Où sont stockées mes données ?</strong></p><p>R : Dans le conteneur sandboxé :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.clipboard/Data/Library/Application Support/com.w3cub.clipboard/</span></span></code></pre></div><p>Les clés API résident dans le Keychain système, pas dans ce dossier.</p>',25)])])}const g=t(a,[["render",o]]);export{m as __pageData,g as default};
